:root {
  --background: oklch(0.985 0.004 270);
  --foreground: oklch(0.2 0.03 275);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.2 0.03 275);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2 0.03 275);
  --primary: oklch(0.5 0.24 280);
  --primary-foreground: oklch(0.98 0.01 280);
  --secondary: oklch(0.95 0.015 275);
  --secondary-foreground: oklch(0.25 0.04 275);
  --muted: oklch(0.96 0.01 275);
  --muted-foreground: oklch(0.52 0.03 275);
  --accent: oklch(0.94 0.03 280);
  --accent-foreground: oklch(0.25 0.04 275);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(0.98 0.01 280);
  --border: oklch(0.91 0.012 275);
  --input: oklch(0.89 0.015 275);
  --ring: oklch(0.5 0.24 280);
  --highlight: oklch(0.65 0.2 330);
  --highlight-foreground: oklch(0.98 0.01 280);
  --glow: oklch(0.6 0.24 285);
  --chart-1: oklch(0.5 0.24 280);
  --chart-2: oklch(0.65 0.2 330);
  --chart-3: oklch(0.7 0.15 200);
  --chart-4: oklch(0.75 0.15 90);
  --chart-5: oklch(0.6 0.18 150);
  --sidebar: oklch(0.97 0.008 275);
  --sidebar-foreground: oklch(0.2 0.03 275);
  --sidebar-primary: oklch(0.5 0.24 280);
  --sidebar-primary-foreground: oklch(0.98 0.01 280);
  --sidebar-accent: oklch(0.94 0.03 280);
  --sidebar-accent-foreground: oklch(0.25 0.04 275);
  --sidebar-border: oklch(0.91 0.012 275);
  --sidebar-ring: oklch(0.5 0.24 280);

  --typeface-body: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --typeface-display: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  --page-width: 76rem;
  --page-gutter: 1rem;
  --section-y: 4rem;
}

.dark {
  --background: oklch(0.14 0.03 275);
  --foreground: oklch(0.96 0.01 275);
  --card: oklch(0.18 0.035 275);
  --card-foreground: oklch(0.96 0.01 275);
  --popover: oklch(0.18 0.035 275);
  --popover-foreground: oklch(0.96 0.01 275);
  --primary: oklch(0.68 0.2 285);
  --primary-foreground: oklch(0.14 0.03 275);
  --secondary: oklch(0.22 0.04 275);
  --secondary-foreground: oklch(0.96 0.01 275);
  --muted: oklch(0.21 0.035 275);
  --muted-foreground: oklch(0.7 0.03 275);
  --accent: oklch(0.25 0.05 280);
  --accent-foreground: oklch(0.96 0.01 275);
  --destructive: oklch(0.66 0.2 25);
  --destructive-foreground: oklch(0.98 0.01 280);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 14%);
  --ring: oklch(0.68 0.2 285);
  --highlight: oklch(0.75 0.17 330);
  --highlight-foreground: oklch(0.14 0.03 275);
  --glow: oklch(0.6 0.26 288);
  --chart-1: oklch(0.68 0.2 285);
  --chart-2: oklch(0.75 0.17 330);
  --chart-3: oklch(0.75 0.13 200);
  --chart-4: oklch(0.8 0.14 90);
  --chart-5: oklch(0.7 0.16 150);
  --sidebar: oklch(0.17 0.033 275);
  --sidebar-foreground: oklch(0.96 0.01 275);
  --sidebar-primary: oklch(0.68 0.2 285);
  --sidebar-primary-foreground: oklch(0.14 0.03 275);
  --sidebar-accent: oklch(0.25 0.05 280);
  --sidebar-accent-foreground: oklch(0.96 0.01 275);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.68 0.2 285);
}
